from pathlib import Path
root=Path('E:/cxy/09-设计与原型/自定义活动管理')
source=Path('E:/cxy/09-设计与原型/自定义活动管理/custom-activity.html').read_text(encoding='utf-8')
style=source[source.index('<style>'):source.index('</style>')+8]
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>活动核销</title><body style="margin:0"><div id="custom-activity">STYLE<main><h1>活动核销</h1><section><h2>基础信息</h2><div class="grid"><label>经销商全称<input readonly id="dealer-name"></label><label>系统名称<input readonly id="system-name"></label><label>负责人<input readonly value="当前登录用户（演示）"></label><label class="wide">关联营销活动申请单<input readonly value="HD-DEMO-001 · 自定义活动（演示）"></label><label>活动日期<input readonly id="dates"></label><label>我司实际承担费用合计（元）<input readonly id="actual-sum" value="待执行填报"></label><label>支付方式<input readonly id="pay"></label><label class="wide"><span><em>*</em> 活动总结</span><textarea form="writeoff" required placeholder="填写活动执行情况及核销说明"></textarea></label></div></section><details><summary style="padding:20px;background:var(--p-panel)">活动信息 · 展开查看完整申请表单（只读）</summary><div id="snapshot"></div></details><section><h2>执行情况</h2><div class="table-wrap"><table><thead><tr><th>费用项</th><th>申请预算（元）</th><th>实际费用（元）</th><th>我司承担比例</th><th>支付方式</th></tr></thead><tbody id="execution-rows"></tbody></table></div><h3>执行附件</h3><ul id="execution-files"></ul><small>执行费用和附件只读，需修改时返回“活动执行填报”。</small></section><section><h2>核销信息</h2><form id="writeoff"><div class="grid"><label><span><em>*</em> 本次核销金额（元）</span><input required id="amount" type="number" min="0" step="0.01" placeholder="填写本次核销金额"></label><label>本次核销日期<input required id="date" type="date"></label><label>补充附件（选填）<input id="extra" type="file" multiple></label></div><ul id="extra-list"></ul><div class="footer"><small>演示页面，未连接真实审批及历史核销数据。</small><button type="submit" class="primary">提交核销</button></div><div id="feedback" role="status" aria-live="polite"></div></form></section></main></div><script>
(()=>{const q=s=>document.querySelector(s);let available=null;function sync(){try{const app=parent.document.getElementById('application').contentDocument,execWin=parent.document.getElementById('execution').contentWindow;execWin.syncApplicationSnapshot?.();const exe=execWin.document;const fields=app.querySelectorAll('.basic-grid input');q('#dealer-name').value=fields[0]?.value||'';q('#system-name').value=fields[1]?.value||'';q('#dates').value=app.querySelector('#start').value+' 至 '+app.querySelector('#end').value;q('#pay').value=app.querySelector('#payment').value;const snapshot=q('#snapshot');snapshot.replaceChildren();const original=exe.querySelector('#application-snapshot');if(original)Array.from(original.children).forEach(el=>snapshot.append(el.cloneNode(true)));snapshot.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=true);const tb=q('#execution-rows');tb.replaceChildren();let sum=0,complete=true;exe.querySelectorAll('#costs tr').forEach(row=>{const tr=document.createElement('tr');Array.from(row.cells).forEach((cell,i)=>{const td=document.createElement('td');const input=cell.querySelector('input');td.textContent=input?(input.value===''?'待填写':Number(input.value).toFixed(2)):cell.textContent;if(input){if(input.value===''||!input.checkValidity())complete=false;else sum+=Number(input.value)}tr.append(td)});tb.append(tr)});const percent=Number(app.querySelector('#company-percent').value);available=complete?Math.round(sum*percent)/100:null;q('#actual-sum').value=available===null?'待执行填报':available.toFixed(2);const list=q('#execution-files');list.replaceChildren();const files=exe.querySelector('#execution-files')?.files;if(files?.length)Array.from(files).forEach(file=>{const li=document.createElement('li');li.textContent=file.name;list.append(li)});else{const li=document.createElement('li');li.textContent='暂无执行附件';list.append(li)}}catch{q('#feedback').textContent='请在活动管理合并页面中打开，以读取申请和执行数据。'}}window.syncWriteoff=sync;sync();q('#extra').onchange=()=>{q('#extra-list').replaceChildren();Array.from(q('#extra').files).forEach(f=>{const li=document.createElement('li');li.textContent=f.name;q('#extra-list').append(li)})};q('#writeoff').onsubmit=e=>{e.preventDefault();sync();const value=Number(q('#amount').value);q('#feedback').textContent=available===null?'请先完成活动执行的实际费用填报。':value>available?'本次核销金额不能超过我司实际承担费用。':'校验通过，演示页面未提交真实核销。'}})();
</script></body></html>'''
(root/'活动核销.html').write_text(page.replace('STYLE',style),encoding='utf-8')
m=root/'tools/merge-activity-pages.py'
s=m.read_text(encoding='utf-8')
s=s.replace("execution=(root/'活动执行填报.html').read_text(encoding='utf-8')","execution=(root/'活动执行填报.html').read_text(encoding='utf-8')\nwriteoff=(root/'活动核销.html').read_text(encoding='utf-8')")
s=s.replace('<div class="hint">','<button type="button" aria-controls="writeoff" data-page="writeoff">活动核销</button><div class="hint">')
s=s.replace('</main></div><script>','<iframe id="writeoff" title="活动核销" hidden srcdoc="WRITEOFF"></iframe></main></div><script>')
s=s.replace("document.title=button.textContent+' · 活动管理';","document.title=button.textContent+' · 活动管理';if(button.dataset.page==='writeoff'){document.getElementById('writeoff').contentWindow.syncWriteoff?.()};")
s=s.replace(".replace('EXECUTION',escape(execution,quote=True))",".replace('EXECUTION',escape(execution,quote=True)).replace('WRITEOFF',escape(writeoff,quote=True))")
m.write_text(s,encoding='utf-8')
